    /// <summary>
    /// Base de conocimiento del asistente del sitio (nov-2026). Solo datos: el motor que
    /// entiende las preguntas está en AsistenteWebService.
    ///
    /// Cada tema tiene palabras clave (se reconocen con o sin tildes, en plural o con
    /// errores de tipeo), una o más respuestas, botones de acción y sugerencias para seguir
    /// la conversación. En las respuestas: {correo} y {saludo} se reemplazan al responder.
    /// Acciones: cotizar, solicitar, itinerarios, portal, registro, formulario, wsp,
    /// armar (armar la cotización en el chat) o pag:{slug} (página de un servicio).
    ///
    /// Para agregar una respuesta basta con sumar un Tema a la lista.
    /// </summary>
    public record TemaAsistente(string Id, string Grupo, string[] Claves, string[] Respuestas,
        string[]? Acciones = null, string[]? Sugerencias = null);

